// Digital twin for Sense.TOF — ams-OSRAM TMF8806 direct time-of-flight ranging
// sensor. The physical world (object distance, return strength, die temp) is
// driven by the controls; host calls return the result record exactly as
// firmware reads it (distance in mm, reliability 0..63, result counter), and the
// INT pin (pad 9) asserts when a measurement result is ready.
//
// Pad note: chip GPIO0 is on tile pad 3 with a 100k on-board pull-up to V+. It
// is a hardware strap (holds GPIO0 high → selects 1.8-3.3V digital I/O for the
// 2.7-3.6V rail), NOT an I2C-address strap and NOT a runtime control — so it is
// not modeled as a driven pad output here.
import type { TileSim } from '../tileSim';

interface State {
  // ── physical world ──
  distance_mm: number; // object distance from the sensor
  reliability: number; // return strength / confidence, 0..63
  temperature: number; // die temperature °C

  // ── operation ──
  measuring: number; // ranging active (start/stop)
  int_enabled: number; // result interrupt enabled

  // ── configuration ──
  mode: number; // 0 short(~200mm) 1 2500mm 2 5000mm
  period_ms: number; // repetition period code (0x1E=30ms, 0=single-shot)
  threshold: number; // detection threshold 0..63
  kilo_iters: number; // iterations in thousands (SNR/power tradeoff)
  result_number: number; // monotonic result counter (wraps 256)

  // ── threshold-interrupt window ──
  thr_int_on: number;
  thr_low_mm: number;
  thr_high_mm: number;
  persistence: number;

  calib_valid: number;

  [field: string]: number;
}

const I2C_ADDR = 0x41;
const PRESENCE_RELIABILITY_MIN = 32; // driver constant for "object present"

// Max range for the active distance mode (datasheet algorithm modes).
function maxRange(mode: number): number {
  return mode === 0 ? 200 : mode === 2 ? 5000 : 2500;
}
// Effective return: beyond max range there's no target (distance 0, reliability 0).
function effDistance(s: State): number {
  return s.distance_mm <= maxRange(s.mode) ? s.distance_mm : 0;
}
function effReliability(s: State): number {
  return s.distance_mm <= maxRange(s.mode) ? s.reliability : 0;
}

// Modeled signal-quality diagnostics [reference_hits, object_hits, crosstalk].
// Reference hits are a ~constant internal channel; object hits scale with the
// return strength (more iterations → more photons); crosstalk is the small,
// calibrated optical-leakage floor. All inferred (no datasheet-exact values).
function signalQuality(s: State): number[] {
  const rel = effReliability(s);
  const iterScale = s.kilo_iters / 900; // relative to the default integration
  const referenceHits = Math.round(180000 * iterScale);
  const objectHits = Math.round((rel / 63) * 150000 * iterScale);
  const crosstalk = 480;
  return [referenceHits, objectHits, crosstalk];
}

const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;

const sim: TileSim<State> = {
  tile: 'Sense.TOF',

  defaultState: {
    distance_mm: 1000,
    reliability: 40,
    temperature: 25,

    measuring: 1,
    int_enabled: 1,

    mode: 1, // 2500 mm
    period_ms: 0x1e, // 30 ms
    threshold: 6,
    kilo_iters: 900,
    result_number: 0,

    thr_int_on: 0,
    thr_low_mm: 0,
    thr_high_mm: 0,
    persistence: 0,

    calib_valid: 0,
  },

  controls: [
    {
      type: 'slider',
      field: 'distance_mm',
      label: 'Object distance',
      min: 0,
      max: 5000,
      step: 10,
      unit: 'mm',
    },
    { type: 'slider', field: 'reliability', label: 'Return strength', min: 0, max: 63, step: 1 },
    {
      type: 'slider',
      field: 'temperature',
      label: 'Temperature',
      min: -40,
      max: 85,
      step: 1,
      unit: '°C',
    },
    { type: 'slider', field: 'measuring', label: 'Measuring', min: 0, max: 1, step: 1 },
    { type: 'slider', field: 'int_enabled', label: 'Result interrupt', min: 0, max: 1, step: 1 },
  ],

  hostCalls: {
    // ── lifecycle ──
    tile_sense_tof_find: () => ({ scalar: I2C_ADDR }),
    tile_sense_tof_init: () => ({ scalar: 0, nextState: { mode: 1, period_ms: 0x1e } }),
    tile_sense_tof_sleep: () => ({ nextState: { measuring: 0 } }),
    tile_sense_tof_wake: () => ({ nextState: {} }),
    tile_sense_tof_reset: () => ({ nextState: { result_number: 0 } }),
    tile_sense_tof_start: () => ({ nextState: { measuring: 1 } }),
    tile_sense_tof_stop: () => ({ nextState: { measuring: 0 } }),

    // ── results ──
    tile_sense_tof_get_distance_mm: ({ state }) => ({ scalar: effDistance(state) }),
    tile_sense_tof_get_result: ({ state }) => ({
      array: [effDistance(state), 0, effReliability(state), state.temperature, state.result_number],
    }),
    tile_sense_tof_get_result_flat: ({ state }) => ({
      array: [effDistance(state), 0, effReliability(state), state.temperature, state.result_number],
    }),
    tile_sense_tof_measure_single: ({ state }) => ({
      scalar: 1,
      nextState: { result_number: (state.result_number + 1) & 0xff },
    }),
    tile_sense_tof_measure_single_flat: ({ state }) => ({
      array: [
        effDistance(state),
        0,
        effReliability(state),
        state.temperature,
        (state.result_number + 1) & 0xff,
      ],
    }),
    tile_sense_tof_result_ready: ({ state }) => ({ scalar: state.measuring }),
    tile_sense_tof_read_distance_with_confidence: ({ state }) => ({
      array: [effDistance(state), Math.round((effReliability(state) * 100) / 63)],
    }),
    tile_sense_tof_is_object_within: ({ state, args }) => ({
      scalar:
        effDistance(state) > 0 &&
        effDistance(state) <= pick(args, 0, maxRange(state.mode)) &&
        effReliability(state) >= PRESENCE_RELIABILITY_MIN
          ? 1
          : 0,
    }),
    tile_sense_tof_wait_for_object: ({ state, args }) => ({
      scalar:
        effDistance(state) > 0 &&
        effDistance(state) <= pick(args, 0, maxRange(state.mode)) &&
        effReliability(state) >= PRESENCE_RELIABILITY_MIN
          ? 1
          : 0,
    }),
    tile_sense_tof_get_sys_clock_ticks: ({ state }) => ({
      scalar: (state.result_number * 4700) >>> 0,
    }),

    // ── configuration ──
    tile_sense_tof_set_distance_mode: ({ state, args }) => ({
      nextState: { mode: pick(args, 0, state.mode) },
    }),
    tile_sense_tof_set_period: ({ state, args }) => ({
      nextState: { period_ms: pick(args, 0, state.period_ms) },
    }),
    tile_sense_tof_set_kilo_iters: ({ state, args }) => ({
      nextState: { kilo_iters: pick(args, 0, state.kilo_iters) },
    }),
    tile_sense_tof_set_threshold: ({ state, args }) => ({
      nextState: { threshold: pick(args, 0, state.threshold) & 0x3f },
    }),
    tile_sense_tof_get_signal_quality: ({ state }) => ({ array: signalQuality(state) }),
    tile_sense_tof_get_signal_quality_flat: ({ state }) => ({ array: signalQuality(state) }),
    tile_sense_tof_set_threshold_interrupt: ({ args }) => {
      const persistence = pick(args, 0, 0);
      const low = pick(args, 1, 0);
      const high = pick(args, 2, 0);
      return {
        scalar: low <= high ? 1 : 0,
        nextState: {
          persistence,
          thr_low_mm: low,
          thr_high_mm: high,
          thr_int_on: low <= high ? 1 : 0,
        },
      };
    },
    tile_sense_tof_get_threshold_interrupt: ({ state }) => ({
      array: [state.persistence, state.thr_low_mm, state.thr_high_mm],
    }),

    // ── calibration / state ──
    tile_sense_tof_factory_calibrate: () => ({ scalar: 1, nextState: { calib_valid: 1 } }),
    tile_sense_tof_set_calibration: () => ({ nextState: { calib_valid: 1 } }),
    tile_sense_tof_get_calibration: () => ({ array: new Array(14).fill(0) }),
    tile_sense_tof_save_state: () => ({ nextState: {} }),
    tile_sense_tof_restore_state: () => ({ nextState: {} }),

    // ── identity ──
    tile_sense_tof_get_app_version: () => ({ array: [1, 2, 0] }),
    tile_sense_tof_get_app_version_flat: () => ({ array: [1, 2, 0] }),
    tile_sense_tof_get_serial_number: () => ({ array: [0, 0, 0, 0] }),
    tile_sense_tof_get_serial_number_flat: () => ({ scalar: 0 }),

    // ── histogram (diagnostic) ──
    tile_sense_tof_read_histogram: () => ({ scalar: 0 }),
    tile_sense_tof_read_histogram_flat: () => ({ array: [] }),
  },

  provenance: {
    // canonical — datasheet result layout / conversions
    tile_sense_tof_find: 'canonical', // I2C 0x41
    tile_sense_tof_get_distance_mm: 'canonical', // distance = MSB<<8 | LSB (mm)
    tile_sense_tof_get_result: 'canonical', // result record layout
    tile_sense_tof_get_result_flat: 'canonical',
    tile_sense_tof_measure_single_flat: 'canonical',
    tile_sense_tof_read_distance_with_confidence: 'canonical', // reliability*100/63
    tile_sense_tof_get_sys_clock_ticks: 'inferred', // fabricated monotonic ramp, not the real 4.7 MHz counter
    tile_sense_tof_set_distance_mode: 'canonical', // algo byte / ranges
    tile_sense_tof_set_period: 'canonical', // repetition period code
    tile_sense_tof_set_kilo_iters: 'canonical', // cmd_data1/0 kIters
    tile_sense_tof_set_threshold: 'canonical', // cmd_data3[5:0]
    tile_sense_tof_set_threshold_interrupt: 'canonical', // WR_ADD_CONFIG format
    // inferred — behavioral simplifications, not the exact chip bits/values
    tile_sense_tof_result_ready: 'inferred', // returns "measuring", not the INT_STATUS bit
    tile_sense_tof_get_signal_quality: 'inferred', // modeled hit counts
    tile_sense_tof_get_signal_quality_flat: 'inferred',
    // hallucinated — stubbed / opaque
    tile_sense_tof_read_histogram: 'hallucinated',
    tile_sense_tof_read_histogram_flat: 'hallucinated',
    tile_sense_tof_get_serial_number: 'hallucinated',
    tile_sense_tof_get_serial_number_flat: 'hallucinated',
    tile_sense_tof_get_calibration: 'hallucinated',
    tile_sense_tof_set_calibration: 'hallucinated',
    tile_sense_tof_save_state: 'hallucinated',
    tile_sense_tof_restore_state: 'hallucinated',
    power: 'canonical', // TMF8806 Table 4 electrical characteristics
    // (everything else defaults to "inferred")
  },

  // Each tick is a completed measurement while ranging.
  deriveState(state) {
    if (state.measuring === 1) return { result_number: (state.result_number + 1) & 0xff };
    return {};
  },

  // INT pin: asserts on result-ready (interrupt enabled). With a threshold
  // window configured, only fires when the object is inside [low, high].
  // (Hardware INT is active-low; here 1 = asserted for clarity.)
  padOutputs(state) {
    const resultInt = state.measuring === 1 && state.int_enabled === 1;
    const inWindow =
      state.thr_int_on === 0 ||
      (effDistance(state) >= state.thr_low_mm && effDistance(state) <= state.thr_high_mm);
    return { INT: resultInt && inWindow ? 1 : 0 };
  },

  // Electrical (TMF8806 datasheet, 2.8 V): standby 85 µA; ranging average
  // 25.8 mA (2.5 m / 33 ms / 900k iterations). VCSEL peaks ~230 mA internally.
  power(state) {
    const ranging = state.measuring === 1;
    const ua = ranging ? 25800 : 85;
    return {
      draw_ua: ua,
      rails: [
        {
          name: 'V+',
          role: 'supply',
          v_mv: 2800,
          i_ua: ua,
          pads: ['10'],
          note: ranging ? 'ranging avg (VCSEL peak ~230 mA)' : 'standby',
        },
      ],
    };
  },
};

export default sim;
